(function() {
    'use strict';

    class FiveStarsFBAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'FiveStars F&B';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    month: 'January',
                    monthEs: 'Enero',
                    seasonFactor: 0.70,
                    occupancy: 0.55,
                    briefing: 'Low-occupancy winter month. Tourism is slow but steady. Focus on cost control and operational experimentation. A small corporate group has inquired about a dinner.',
                    briefingEs: 'Mes de invierno con baja ocupacion. El turismo es lento pero constante. Enfoque en control de costos y experimentacion operativa. Un grupo corporativo ha consultado sobre una cena.',
                    eventType: 'Corporate Dinner',
                    eventTypeEs: 'Cena Corporativa',
                    eventGuests: 40,
                    eventBudget: 50,
                    eventDesc: 'A local company requests a plated dinner for 40 executives. Budget: $50 per person. Formal service required.',
                    eventDescEs: 'Una empresa local solicita una cena con servicio a la mesa para 40 ejecutivos. Presupuesto: $50 por persona. Servicio formal requerido.'
                },
                {
                    month: 'February',
                    monthEs: 'Febrero',
                    seasonFactor: 0.80,
                    occupancy: 0.60,
                    briefing: 'Shoulder season begins. Valentine is Day drives a spike in romantic dining demand. Couples packages and premium wine pairings are in high demand.',
                    briefingEs: 'Comienza la temporada intermedia. San Valentin impulsa la demanda de cenas romanticas. Los paquetes para parejas y maridajes premium tienen alta demanda.',
                    eventType: 'Valentine Gala',
                    eventTypeEs: 'Gala de San Valentin',
                    eventGuests: 60,
                    eventBudget: 65,
                    eventDesc: 'A luxury travel agency requests a Valentine is themed gala dinner for 60 guests. Budget: $65 per person. Cocktail reception followed by 4-course plated dinner.',
                    eventDescEs: 'Una agencia de viajes de lujo solicita una cena de gala tematica de San Valentin para 60 invitados. Presupuesto: $65 por persona. Coctel seguido de cena de 4 tiempos.'
                },
                {
                    month: 'March',
                    monthEs: 'Marzo',
                    seasonFactor: 0.90,
                    occupancy: 0.65,
                    briefing: 'Occupancy is rising steadily. A destination wedding inquiry has arrived. The menu engineering data from prior months should now inform pricing adjustments.',
                    briefingEs: 'La ocupacion sube constantemente. Ha llegado una consulta para boda destino. Los datos de ingenieria de menu de meses anteriores deben informar ajustes de precios.',
                    eventType: 'Destination Wedding',
                    eventTypeEs: 'Boda Destino',
                    eventGuests: 120,
                    eventBudget: 60,
                    eventDesc: 'A couple requests a Saturday evening wedding reception for 120 guests. Budget: $60 per person. Buffet service with cocktail hour. This will use both dining rooms.',
                    eventDescEs: 'Una pareja solicita una recepcion de boda sabado por la noche para 120 invitados. Presupuesto: $60 por persona. Servicio buffet con hora de cocteles. Esto usara ambos comedores.'
                },
                {
                    month: 'April',
                    monthEs: 'Abril',
                    seasonFactor: 1.10,
                    occupancy: 0.75,
                    briefing: 'Easter holidays create a leisure demand spike. Families and international tourists flood the destination. Kitchen capacity is being tested. A large group has inquired about Easter brunch.',
                    briefingEs: 'Las vacaciones de Semana Santa crean un pico de demanda. Familias y turistas internacionales llegan al destino. La capacidad de cocina esta siendo puesta a prueba. Un grupo grande consulta sobre un brunch de Pascua.',
                    eventType: 'Easter Brunch',
                    eventTypeEs: 'Brunch de Pascua',
                    eventGuests: 80,
                    eventBudget: 55,
                    eventDesc: 'A tour operator requests an Easter Sunday brunch for 80 guests including families with children. Budget: $55 per person. Buffet with live cooking stations.',
                    eventDescEs: 'Un operador turistico solicita un brunch de Pascua para 80 invitados incluyendo familias con ninos. Presupuesto: $55 por persona. Buffet con estaciones de cocina en vivo.'
                },
                {
                    month: 'May',
                    monthEs: 'Mayo',
                    seasonFactor: 1.20,
                    occupancy: 0.80,
                    briefing: 'Peak conference season. Business travelers fill the hotel. Group dining and corporate event demand is at its highest. The Rooftop Bar is booming with after-conference crowds.',
                    briefingEs: 'Temporada alta de conferencias. Viajeros de negocios llenan el hotel. La demanda de eventos corporativos esta en su punto mas alto. El Bar Terraza esta lleno con publico post-conferencia.',
                    eventType: 'Corporate Gala',
                    eventTypeEs: 'Gala Corporativa',
                    eventGuests: 150,
                    eventBudget: 70,
                    eventDesc: 'A multinational corporation requests a gala dinner for 150 attendees tied to their annual conference. Budget: $70 per person. Plated 5-course dinner with open bar.',
                    eventDescEs: 'Una corporacion multinacional solicita una cena de gala para 150 asistentes vinculada a su conferencia anual. Presupuesto: $70 por persona. Cena de 5 tiempos con barra libre.'
                },
                {
                    month: 'June',
                    monthEs: 'Junio',
                    seasonFactor: 1.05,
                    occupancy: 0.72,
                    briefing: 'Summer tourism begins. School holidays drive family travel. Conference season winds down but leisure demand compensates. A large wedding inquiry closes the half-year.',
                    briefingEs: 'Comienza el turismo de verano. Las vacaciones escolares impulsan el turismo familiar. La temporada de conferencias termina pero la demanda de ocio compensa. Una gran consulta de boda cierra el semestre.',
                    eventType: 'Summer Wedding',
                    eventTypeEs: 'Boda de Verano',
                    eventGuests: 100,
                    eventBudget: 62,
                    eventDesc: 'A wedding planner requests a Saturday garden reception for 100 guests. Budget: $62 per person. Cocktail-style service with food stations and live music area.',
                    eventDescEs: 'Un organizador de bodas solicita una recepcion de jardin sabado para 100 invitados. Presupuesto: $62 por persona. Servicio estilo coctel con estaciones de comida y area de musica en vivo.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 433000,
                    totalRevenue: 0,
                    totalCOGS: 0,
                    totalLabor: 0,
                    totalPromoSpend: 0,
                    totalEventRevenue: 0,
                    totalEBITDA: 0,
                    guestSatisfaction: 7.0,
                    reputation: 7.0,
                    cumulativeCovers: 0,
                    cumulativeLaborHours: 0,
                    profitHistory: [],
                    revenueHistory: [],
                    satisfactionHistory: [],
                    foodCostPctHistory: [],
                    eventRevenueHistory: [],
                    laborProdHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    menuPrice: 52,
                    menuStrategy: 'balanced',
                    freshnessMix: 50,
                    cookTier: 2,
                    serverCount: 16,
                    casualHours: 4,
                    eventAccept: true,
                    eventPrice: 60,
                    promoSpend: 8000,
                    promoFocus: 'loyalty'
                };
            }
            this._updateBriefing(state);
            this._setupFreshnessSlider();
        }

        _setupFreshnessSlider() {
            var slider = document.getElementById('freshnessInput');
            var display = document.getElementById('freshnessValue');
            if (slider && display) {
                slider.addEventListener('input', function() {
                    display.textContent = slider.value;
                });
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = (window.mySimulation && window.mySimulation.currentLanguage) || 'en';
            var isEs = lang === 'es';

            var monthEl = document.getElementById('monthName');
            if (monthEl) monthEl.textContent = isEs ? round.monthEs : round.month;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.textContent = isEs ? round.briefingEs : round.briefing;

            var eventDescEl = document.getElementById('eventDescription');
            if (eventDescEl) {
                var typeLabel = isEs ? round.eventTypeEs : round.eventType;
                var desc = isEs ? round.eventDescEs : round.eventDesc;
                eventDescEl.innerHTML = '<strong>' + typeLabel + '</strong> (' + round.eventGuests + ' ' + (isEs ? 'invitados' : 'guests') + ')<br>' + desc;
            }

            var eventPriceInput = document.getElementById('eventPriceInput');
            if (eventPriceInput) {
                eventPriceInput.value = round.eventBudget;
            }
        }

        validateDecisions(decisions) {

            var menuPriceEl = document.getElementById('menuPriceInput');
            if (menuPriceEl) decisions.menuPrice = parseFloat(menuPriceEl.value);

            var strategyEl = document.getElementById('menuStrategySelect');
            if (strategyEl) decisions.menuStrategy = strategyEl.value;

            var freshnessEl = document.getElementById('freshnessInput');
            if (freshnessEl) decisions.freshnessMix = parseInt(freshnessEl.value);

            var cookTierEl = document.getElementById('cookTierSelect');
            if (cookTierEl) decisions.cookTier = parseInt(cookTierEl.value);

            var serverEl = document.getElementById('serverCountSelect');
            if (serverEl) decisions.serverCount = parseInt(serverEl.value);

            var casualEl = document.getElementById('casualHoursInput');
            if (casualEl) decisions.casualHours = parseInt(casualEl.value);

            var eventAcceptEl = document.getElementById('eventAcceptCheck');
            if (eventAcceptEl) decisions.eventAccept = eventAcceptEl.checked;

            var eventPriceEl = document.getElementById('eventPriceInput');
            if (eventPriceEl) decisions.eventPrice = parseFloat(eventPriceEl.value);

            var promoEl = document.getElementById('promoSpendInput');
            if (promoEl) decisions.promoSpend = parseFloat(promoEl.value);

            var promoFocusEl = document.getElementById('promoFocusSelect');
            if (promoFocusEl) decisions.promoFocus = promoFocusEl.value;

            if (!decisions.menuPrice || decisions.menuPrice < 35 || decisions.menuPrice > 75) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('price_warning'), 'warning'
                );
                return false;
            }
            if (decisions.freshnessMix < 0 || decisions.freshnessMix > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('freshness_warning'), 'warning'
                );
                return false;
            }
            if (decisions.promoSpend < 0 || decisions.promoSpend > 15000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('promo_warning'), 'warning'
                );
                return false;
            }
            if (decisions.eventAccept && (decisions.eventPrice < 40 || decisions.eventPrice > 90)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('event_price_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var seasonFactor = round.seasonFactor;
            var occupancy = round.occupancy;
            var freshPct = d.freshnessMix / 100;

            var repFactor = 0.8 + (ds.reputation / 10) * 0.4;

            var priceElasticity = 1.0;
            if (d.menuPrice > 55) {
                priceElasticity = 1 - (d.menuPrice - 55) * 0.012;
            } else if (d.menuPrice < 45) {
                priceElasticity = 1 + (45 - d.menuPrice) * 0.008;
            }
            priceElasticity = Math.max(0.5, Math.min(1.3, priceElasticity));

            var freshDemandBonus = 1 + (freshPct - 0.5) * 0.12;

            var strategyMultiplier = 1.0;
            var strategyCostAdj = 0;
            if (d.menuStrategy === 'stars') {
                strategyMultiplier = 0.92;
                strategyCostAdj = -0.03;
            } else if (d.menuStrategy === 'volume') {
                strategyMultiplier = 1.10;
                strategyCostAdj = 0.02;
            } else if (d.menuStrategy === 'innovation') {
                strategyMultiplier = 0.95;
                strategyCostAdj = -0.01;
            }

            var promoBoost = 1 + (d.promoSpend / 15000) * 0.08;
            if (d.promoFocus === 'seasonal') {
                promoBoost += seasonFactor > 1.0 ? 0.04 : 0.01;
            } else if (d.promoFocus === 'upselling') {
                promoBoost += 0.02;
            }

            var noise = 0.95 + Math.random() * 0.10;

            var baseMainCovers = 1500;
            var mainCovers = Math.round(baseMainCovers * seasonFactor * priceElasticity * freshDemandBonus * repFactor * strategyMultiplier * promoBoost * noise);
            mainCovers = Math.max(400, Math.min(3000, mainCovers));

            var baseBarCovers = 1000;
            var barCovers = Math.round(baseBarCovers * seasonFactor * repFactor * promoBoost * noise);
            if (d.promoFocus === 'upselling') barCovers = Math.round(barCovers * 1.10);
            barCovers = Math.max(300, Math.min(2000, barCovers));

            var baseRSOrders = 667;
            var rsOrders = Math.round(baseRSOrders * occupancy * 1.5 * noise);
            rsOrders = Math.max(200, Math.min(1200, rsOrders));

            var mainRevenue = mainCovers * d.menuPrice;
            var barADR = 14;
            if (d.promoFocus === 'upselling') barADR = 16;
            var barRevenue = barCovers * barADR;
            var rsRevenue = rsOrders * 28;

            var eventRevenue = 0;
            var eventCovers = 0;
            var eventAccepted = false;
            if (d.eventAccept) {
                var acceptProb = 1.0;
                if (d.eventPrice > round.eventBudget * 1.15) {
                    acceptProb = Math.max(0.1, 1 - (d.eventPrice - round.eventBudget * 1.15) / (round.eventBudget * 0.5));
                }
                if (Math.random() < acceptProb) {
                    eventAccepted = true;
                    eventCovers = round.eventGuests;
                    eventRevenue = eventCovers * d.eventPrice;
                }
            }

            var totalRevenue = mainRevenue + barRevenue + rsRevenue + eventRevenue;
            var totalCovers = mainCovers + barCovers + rsOrders + eventCovers;

            var mainCOGSPct = 0.28 + freshPct * 0.07 + strategyCostAdj;
            var mainCOGS = mainRevenue * mainCOGSPct;
            var barCOGS = barRevenue * 0.20;
            var rsCOGS = rsRevenue * 0.38;
            var eventCOGS = eventRevenue * 0.28;
            var totalCOGS = mainCOGS + barCOGS + rsCOGS + eventCOGS;

            var wastePct = freshPct * 0.05 * (1.2 - occupancy);
            var wasteCost = (mainCOGS + eventCOGS) * wastePct;
            totalCOGS += wasteCost;

            var foodCostPct = totalRevenue > 0 ? (totalCOGS / totalRevenue) * 100 : 0;

            var chefCost = 6500;
            var cookCost = d.cookTier * 2000;
            var serverCost = d.serverCount * 1500;
            var casualCost = d.casualHours * 30 * 25;
            var totalLabor = chefCost + cookCost + serverCost + casualCost;

            var operatingSupplies = totalRevenue * 0.05;
            var ccProcessing = totalRevenue * 0.03;

            var ebitda = totalRevenue - totalCOGS - totalLabor - operatingSupplies - ccProcessing - d.promoSpend;

            var cookCapacity = [0, 100, 150, 200][d.cookTier] || 150;
            var dailyMainCovers = mainCovers / 30;
            var kitchenUtil = dailyMainCovers / cookCapacity;

            var coversPerServer = (mainCovers + barCovers) / 30 / d.serverCount;
            var serverQuality = coversPerServer < 4 ? 1.0 : coversPerServer < 6 ? 0.9 : coversPerServer < 8 ? 0.75 : 0.5;

            var kitchenQuality = kitchenUtil < 0.85 ? 1.0 : kitchenUtil < 1.0 ? 0.85 : kitchenUtil < 1.2 ? 0.65 : 0.4;

            var freshQuality = 0.6 + freshPct * 0.4;

            var qualityInvestBonus = 0;
            if (d.promoFocus === 'quality') qualityInvestBonus = (d.promoSpend / 15000) * 0.5;

            var rawSatisfaction = 3.5 + serverQuality * 2.0 + kitchenQuality * 2.0 + freshQuality * 2.0 + qualityInvestBonus;
            var valuePenalty = 0;
            if (d.menuPrice > 60) valuePenalty = (d.menuPrice - 60) * 0.03;
            rawSatisfaction -= valuePenalty;
            rawSatisfaction = Math.max(1, Math.min(10, rawSatisfaction));

            ds.guestSatisfaction = Math.round((ds.guestSatisfaction * 0.3 + rawSatisfaction * 0.7) * 10) / 10;
            ds.reputation = Math.round((ds.reputation * 0.5 + ds.guestSatisfaction * 0.5) * 10) / 10;

            var totalLaborHours = (1 * 180) + (d.cookTier * 180) + (d.serverCount * 160) + (d.casualHours * 30);
            var laborProductivity = totalLaborHours > 0 ? Math.round((totalCovers / totalLaborHours) * 10) / 10 : 0;

            ds.cash += ebitda;
            ds.totalRevenue += totalRevenue;
            ds.totalCOGS += totalCOGS;
            ds.totalLabor += totalLabor;
            ds.totalPromoSpend += d.promoSpend;
            ds.totalEventRevenue += eventRevenue;
            ds.totalEBITDA += ebitda;
            ds.cumulativeCovers += totalCovers;
            ds.cumulativeLaborHours += totalLaborHours;

            ds.profitHistory.push(Math.round(ebitda));
            ds.revenueHistory.push(Math.round(totalRevenue));
            ds.satisfactionHistory.push(ds.guestSatisfaction);
            ds.foodCostPctHistory.push(Math.round(foodCostPct * 10) / 10);
            ds.eventRevenueHistory.push(Math.round(eventRevenue));
            ds.laborProdHistory.push(laborProductivity);

            var eventRevPct = ds.totalRevenue > 0 ? (ds.totalEventRevenue / ds.totalRevenue) * 100 : 0;

